def _format_context_blocks(title, blocks):
    lines = [title]
    for heading, body in blocks:
        if not body: continue
        lines.extend(["", heading])
        if isinstance(body, str): lines.append(body)
        else: lines.extend(body)
    return "\n".join(lines).rstrip()

