import ast, copy, json, os, re, shlex
from pathlib import Path

from fastcore.nbio import read_nb
from fastcore.basics import patch

from nbskill.foundation import (track_call, Notebook, Cell, definition_nodes, definition_names, parse_code_cell, cell_analysis,
    scoped_nodes, call_name, cell_matches_type, cell_prefix, cell_source, chapter_spans, find_cell_by_id, first_line, is_exported_code_cell,
    matches_filter, matching_chapters, notebook_paths, notebook_result, one_chapter, source_hash, source_without_directives,
    symbol_short_name)

# %% ../nbs/01_read.ipynb #2bf5140a
def _definition_lines(node, indent=""):
    tmp = copy.deepcopy(node)
    tmp.body = [ast.Pass()]
    ast.fix_missing_locations(tmp)
    lines = []
    for line in ast.unparse(tmp).splitlines():
        if line.strip() == "pass": continue
        lines.append(f"{indent}{line}" if line else line)
    return lines

# %% ../nbs/01_read.ipynb #f18e8160
def _docstring_lines(node, indent="    "):
    doc = ast.get_docstring(node)
    if not doc: return []
    lines = doc.splitlines()
    quote = chr(34) * 3
    if len(lines) == 1: return [f"{indent}{quote}{lines[0]}{quote}"]
    return [indent + quote, *[f"{indent}{line}" for line in lines], indent + quote]

# %% ../nbs/01_read.ipynb #1479f1ce
def _function_overview(node, indent=""): return [*_definition_lines(node, indent=indent), *_docstring_lines(node, indent=indent + "    ")]

# %% ../nbs/01_read.ipynb #0bf698d9
def _class_overview(node):
    lines = [*_definition_lines(node), *_docstring_lines(node)]
    methods = [child for child in node.body if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))]
    for method in methods:
        if lines and lines[-1] != "": lines.append("")
        lines += _function_overview(method, indent="    ")
    return lines

# %% ../nbs/01_read.ipynb #f204f489
def _format_source(source, line_numbers=False):
    if not line_numbers: return source
    lines = source.splitlines() or [""]
    return "\n".join(f"{idx} | {line}" for idx, line in enumerate(lines, start=1))

# %% ../nbs/01_read.ipynb #b1526aff
_QUERY_KEY_ALIASES = dict(id="cell_id", cell="cell_id", cell_id="cell_id", chapter="chapter", section="chapter", type="cell_type",
    cell_type="cell_type", symbol_kind="symbol_kind", kind="symbol_kind", visibility="visibility", contains="contains", text="contains",
    regex="regex", re="regex", error="has_error", errors="has_error", has_error="has_error", checks="has_checks", has_checks="has_checks",
    imports_only="imports_only", export="export", exports="export", exported="export", header="header", headers="header", heading="header",
    headings="header", outline="header")

# %% ../nbs/01_read.ipynb #4f3e6dfd
def _normalize_query_key(key):
    name = _QUERY_KEY_ALIASES.get(str(key).strip().lower())
    if name is None:
        choices = ", ".join(sorted(_QUERY_KEY_ALIASES))
        raise ValueError(f"Unknown query key {key!r}; use one of: {choices}")
    return name

# %% ../nbs/01_read.ipynb #e3f7da55
def _normalize_query_dict(spec): return {_normalize_query_key(key): None if value is None else str(value) for key, value in dict(spec).items()}

# %% ../nbs/01_read.ipynb #cc7d1f47
def _cell_symbol_records(cell):
    definitions = cell_analysis(cell)["definitions"]
    return [dict(symbol=name, kind=kind, visibility="private" if name.rsplit(".", 1)[-1].startswith("_") else "public",
        line=node.lineno) for name, node, kind in definitions or ()]

# %% ../nbs/01_read.ipynb #5b09a9e8
def _parse_query_terms(text):
    spec, bare = {}, []
    for term in shlex.split(str(text)):
        sep = "=" if "=" in term else ":" if ":" in term else None
        if sep is None:
            key = _QUERY_KEY_ALIASES.get(term.strip().lower())
            if key in {"has_error", "export", "header", "has_checks", "imports_only"}: spec[key] = "true"
            else: bare.append(term)
            continue
        key, value = term.split(sep, 1)
        spec[_normalize_query_key(key)] = value
    if bare and "contains" not in spec: spec["contains"] = " ".join(bare)
    return spec

# %% ../nbs/01_read.ipynb #82b26f15
def _parse_query(query):
    if query is None: return [{}]
    if isinstance(query, dict): return [_normalize_query_dict(query)]
    if isinstance(query, (list, tuple)):
        specs = []
        for item in query: specs.extend(_parse_query(item))
        return specs or [{}]

    text = str(query).strip()
    if not text: return [{}]
    try: parsed = json.loads(text)
    except json.JSONDecodeError: return [_parse_query_terms(part) for part in text.split(";") if part.strip()]
    return _parse_query(parsed)

# %% ../nbs/01_read.ipynb #643079c0
def _query_bool(value, default=True):
    if value is None: return default
    return str(value).strip().lower() not in {"0", "false", "no", "off", "none"}

# %% ../nbs/01_read.ipynb #f1cb3b56
def _output_get(output, key, default=None): return output.get(key, default) if isinstance(output, dict) else getattr(output, key, default)

# %% ../nbs/01_read.ipynb #efe04c52
def _cell_has_error(cell): return any(_output_get(output, "output_type") == "error" for output in (getattr(cell, "outputs", []) or []))

# %% ../nbs/01_read.ipynb #e1d82fc4
def _cell_header_level(cell):
    headings = cell_analysis(cell)["headings"]
    return headings[0]["level"] if headings else None

# %% ../nbs/01_read.ipynb #70a031f9
def _cell_matches_header(cell, value):
    level = _cell_header_level(cell)
    if level is None: return False
    text = str(value or "").strip()
    return level == int(text) if text.isdigit() else _query_bool(value)

# %% ../nbs/01_read.ipynb #cc1580d7
def _query_chapter_index_set(nb, name):
    span = _one_chapter_span(nb.cells, name)
    return set(range(span["start"], span["end"]))

# %% ../nbs/01_read.ipynb #03514d3c
def _select_query_items(nb, spec):
    items = [find_cell_by_id(nb.cells, spec["cell_id"])] if spec.get("cell_id") else list(enumerate(nb.cells))
    if spec.get("chapter") is not None:
        chapter_idxs = _query_chapter_index_set(nb, spec["chapter"])
        items = [(i, c) for i, c in items if i in chapter_idxs]
    if spec.get("cell_type") is not None: items = [(i, c) for i, c in items if cell_matches_type(c, spec["cell_type"])]
    if spec.get("symbol_kind") is not None or spec.get("visibility") is not None:
        items = [(i, c) for i, c in items if any((spec.get("symbol_kind") is None or item["kind"] == spec["symbol_kind"])
            and (spec.get("visibility") is None or item["visibility"] == spec["visibility"]) for item in _cell_symbol_records(c))]
    if spec.get("header") is not None: items = [(i, c) for i, c in items if _cell_matches_header(c, spec["header"])]
    if spec.get("export") is not None: items = [(i, c) for i, c in items if is_exported_code_cell(c) == _query_bool(spec["export"])]
    for key in ("has_checks", "imports_only"):
        if spec.get(key) is None: continue
        selected = []
        for idx, cell in items:
            props = Cell(cell).properties()
            value = props["checks"] if key == "has_checks" else props[key]
            if value is not None and bool(value) == _query_bool(spec[key]): selected.append((idx, cell))
        items = selected
    if spec.get("has_error") is not None: items = [(i, c) for i, c in items if _cell_has_error(c) == _query_bool(spec["has_error"])]
    if spec.get("contains") is not None: items = [(i, c) for i, c in items if spec["contains"] in cell_source(c)]
    if spec.get("regex") is not None: items = [(i, c) for i, c in items if matches_filter(cell_source(c), spec["regex"])]
    return items

# %% ../nbs/01_read.ipynb #contextbase
def _context_result(kind, text, verbose=True, **data): return notebook_result({"kind": kind, "text": text, **data})

# %% ../nbs/01_read.ipynb #contextformat
def _notebook_header_items(cells):
    items, started = [], False
    for idx, cell in enumerate(cells):
        if getattr(cell, "cell_type", None) != "markdown":
            if started: break
            continue
        source = cell_source(cell).strip()
        is_h1 = bool(re.search(r"^#\s+", source, flags=re.MULTILINE))
        is_h2 = bool(re.search(r"^##\s+", source, flags=re.MULTILINE))
        if is_h2 and started: break
        if is_h1 or is_h2: started = True
        if started: items.append((idx, cell))
    return items

# %% ../nbs/01_read.ipynb #68e77a75
def _context_match(text, include_re=None, exclude_re=None):
    text = str(text or "")
    if include_re and not re.search(include_re, text, flags=re.MULTILINE): return False
    if exclude_re and re.search(exclude_re, text, flags=re.MULTILINE): return False
    return True

# %% ../nbs/01_read.ipynb #4e1cb1e6
def _format_context_blocks(title, blocks):
    lines = [title]
    for heading, body in blocks:
        if not body: continue
        lines.extend(["", heading])
        if isinstance(body, str): lines.append(body)
        else: lines.extend(body)
    return "\n".join(lines).rstrip()

# %% ../nbs/01_read.ipynb #ef3eae3d
def _definition_record(path, idx, cell, node, symbol=None, kind=None):
    symbol = symbol or _definition_symbol(node)
    kind = kind or ("class" if isinstance(node, ast.ClassDef) else "function")
    lines = _class_overview(node) if isinstance(node, ast.ClassDef) else _function_overview(node)
    return dict(path=str(path), cell_id=getattr(cell, "id", ""), cell_idx=idx, symbol=symbol, kind=kind, text="\n".join(lines))

# %% ../nbs/01_read.ipynb #0126343d
def _definition_records(path, nb):
    records = []
    for idx, cell in enumerate(nb.cells):
        tree = parse_code_cell(cell)
        if tree is None: continue
        records.extend(_definition_record(path, idx, cell, node, symbol=symbol, kind=kind)
            for symbol, node, kind in definition_nodes(tree))
    return records

# %% ../nbs/01_read.ipynb #8cbbb8bd
def _one_chapter_span(cells, name): return one_chapter(cells, name)

# %% ../nbs/01_read.ipynb #c605990b
def _query_items(nb, query):
    items, seen = [], set()
    for spec in _parse_query(query):
        for idx, cell in _select_query_items(nb, spec):
            if idx in seen: continue
            seen.add(idx)
            items.append((idx, cell))
    return items

# %% ../nbs/01_read.ipynb #8b9e0b1e
def _python_ast(path):
    path = Path(path)
    source = path.read_text(encoding="utf-8")
    return source, ast.parse(source, filename=str(path))

# %% ../nbs/01_read.ipynb #e200590a
def _python_doc_first_line(node):
    doc = ast.get_docstring(node) or ""
    return doc.strip().splitlines()[0].strip() if doc.strip() else ""

# %% ../nbs/01_read.ipynb #fc04c094
def _python_source_segment(source, node): return (ast.get_source_segment(source, node) or "").strip()

# %% ../nbs/01_read.ipynb #b774e692
def _python_signature(source, node):
    for line in _python_source_segment(source, node).splitlines():
        line = line.strip()
        if line and not line.startswith("@"): return line
    return ""

# %% ../nbs/01_read.ipynb #883c8735
def _python_call_name(node):
    if isinstance(node, ast.Name): return node.id
    if isinstance(node, ast.Attribute):
        prefix = _python_call_name(node.value)
        return f"{prefix}.{node.attr}" if prefix and prefix != "self" else node.attr
    return ""

# %% ../nbs/01_read.ipynb #e8618628
def _python_calls(node): return sorted({name for name in (_python_call_name(item.func) for item in ast.walk(node) if isinstance(item, ast.Call)) if name})

# %% ../nbs/01_read.ipynb #39129562
def _python_assign_names(node):
    targets = [node.target] if isinstance(node, ast.AnnAssign) else getattr(node, "targets", [])
    return [target.id for target in targets if isinstance(target, ast.Name)]

# %% ../nbs/01_read.ipynb #be7daf99
def _python_definition_records(path):
    path, records = Path(path), []
    source, tree = _python_ast(path)

    def add_record(node, symbol, kind):
        public = not any(part.startswith("_") for part in symbol.split("."))
        records.append(dict(path=str(path), symbol=symbol, kind=kind, public=public, line=getattr(node, 'lineno', 1),
            end_line=getattr(node, 'end_lineno', getattr(node, 'lineno', 1)), signature=_python_signature(source, node),
            docstring=_python_doc_first_line(node), source=_python_source_segment(source, node), calls=_python_calls(node)))

    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            add_record(node, node.name, "async function" if isinstance(node, ast.AsyncFunctionDef) else "function")
        elif isinstance(node, ast.ClassDef):
            add_record(node, node.name, "class")
            for child in node.body:
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)): add_record(child, f"{node.name}.{child.name}", "method")
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            for name in _python_assign_names(node):
                if not name.startswith("_"):
                    records.append(dict(path=str(path), symbol=name, kind='assignment', public=True, line=getattr(node, 'lineno', 1),
                        end_line=getattr(node, 'end_lineno', getattr(node, 'lineno', 1)), signature=_python_signature(source, node),
                        docstring='', source=_python_source_segment(source, node), calls=_python_calls(node)))
    return records

